// Signs Android release builds with the upload key when CI provides it (.github/workflows/android-release.yml).
// android/ is generated by `expo prebuild`, so the signing config is added here, not by editing build.gradle.
// Without SCENESPEAK_UPLOAD_STORE_FILE (local builds, forks) release builds keep Expo's debug signing:
// fine for sideloading and testing, not uploadable to Google Play.
const { withAppBuildGradle } = require("expo/config-plugins");

const MARKER = "// @scenespeak/release-signing";

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.contents.includes(MARKER)) return cfg;
    cfg.modResults.contents += `
${MARKER}
def sceneSpeakStoreFile = System.getenv("SCENESPEAK_UPLOAD_STORE_FILE")
if (sceneSpeakStoreFile) {
    android.signingConfigs.create("sceneSpeakUpload") {
        storeFile file(sceneSpeakStoreFile)
        storePassword System.getenv("SCENESPEAK_UPLOAD_STORE_PASSWORD")
        keyAlias System.getenv("SCENESPEAK_UPLOAD_KEY_ALIAS")
        keyPassword System.getenv("SCENESPEAK_UPLOAD_KEY_PASSWORD")
    }
    android.buildTypes.release.signingConfig android.signingConfigs.sceneSpeakUpload
}
`;
    return cfg;
  });
};
